	-- plural, as words: Twilight Raiders = {npc:256952} Twilight Raider
	["The cultists fill the streets and fields of {area:16723}. Start at the ritual circles in the middle (fill Claire's catalyst there), work west through the burnt houses to the edge of town, then back north-east to the loose soil west of Elbrim's farm: bury the {item:266148} the Twilight Raiders drop there. The charms, pages and finger bones drop from the cultists.\nKeep the {item:4338} they drop: {npc:263613} in {area:16724} asks for twenty when you are back there. Now and then a cultist drops the {quest:94885}: right-click it to start the quest.\nCareful: {npc:256899}, an elite ogre (level 41), walks the western streets of {area:16723}, around 44-47,47-52. Pull the cultists out towards you and let him pass; players died here more than anywhere else in the zone.\n{npc:263380}, the river's elite (level 42), can wander up from the south-western fields: let him pass."] = "Tarikatçılar {area:16723} kasabasının sokaklarını ve tarlalarını dolduruyor. Ortadaki ayin çemberlerinden başla (Claire'in katalizörünü orada doldur), yanık evlerin arasından batıya, kasabanın kenarına kadar çalış, sonra kuzeydoğuya, Elbrim'in çiftliğinin batısındaki gevşek toprağa dön: Twilight Raider yaratıklarının düşürdüğü {item:266148} eşyalarını oraya göm. Tılsımlar, sayfalar ve parmak kemikleri tarikatçılardan düşer.\nDüşürdükleri {item:4338} kumaşını sakla: {area:16724} kalesindeki {npc:263613} oraya döndüğünde yirmi tane ister. Arada bir tarikatçı {quest:94885} düşürür: görevi başlatmak için ona sağ tıkla.\nDikkat: elit bir ogre (seviye 41) olan {npc:256899}, {area:16723} kasabasının batı sokaklarında, yaklaşık 44-47,47-52 çevresinde dolaşıyor. Tarikatçıları kendine doğru çek ve onun geçmesine izin ver; bölgede oyuncuların en çok öldüğü yer burası.\nNehrin elit yaratığı {npc:263380} (seviye 42) güneybatı tarlalarından yukarı gelebilir: geçmesine izin ver.",
	-- {item:269990} Crystal Catalyst
	["fill the {item:269990} at the ritual circles"] = "{item:269990} eşyasını ayin çemberlerinde doldur",
	-- {object:621813} Loose Soil (no name in this language: may be words)
	["{object:621813}: bury the mementos"] = "{object:621813}: hatıraları göm",
	-- {quest:94885} Field Marshal's Log
	["{quest:94885}: only if a cultist dropped the log"] = "{quest:94885}: yalnızca bir tarikatçı günlüğü düşürdüyse",

	-- Step 43: Cut Off the Heads
	-- {npc:256899} Chogg'Zac · {area:16723} Sunnyglade · {npc:257591} Ashe Amberhall · {area:16724} Farholde Keep
	["{npc:256899}, the two-headed ogre, is an elite (level 41) at the western edge of {area:16723}: grouping up is advised. Claire then has the filled catalyst for {npc:257591} in {area:16724}."] = "İki kafalı ogre {npc:256899}, {area:16723} kasabasının batı kenarında elit bir yaratık (seviye 41): grup kurman önerilir. Ardından Claire'de {area:16724} kalesindeki {npc:257591} için dolu katalizör var.",
	-- {quest:94884} An Unsettling Discovery · {npc:257591} Ashe Amberhall · {area:16724} Farholde Keep
	["{quest:94884}: for {npc:257591} in {area:16724}"] = "{quest:94884}: {area:16724} kalesindeki {npc:257591} için",

	-- Step 44: Fuzzle
	-- {npc:259158} Fuzzle · {area:16723} Sunnyglade
	["{npc:259158} wants out of {area:16723}: lead him west to his treasure at the edge of town and keep the cultists off him."] = "{npc:259158}, {area:16723} kasabasından çıkmak istiyor: onu batıya, kasabanın kenarındaki hazinesine götür ve tarikatçıları ondan uzak tut.",
	-- {npc:259158} Fuzzle · {area:16723} Sunnyglade
	["lead {npc:259158} out of {area:16723} to his treasure, west of the town"] = "{npc:259158} yaratığını {area:16723} kasabasından, kasabanın batısındaki hazinesine götür",

	-- Step 45: Farmer Elbrim
	["Back east through the town to Elbrim's farm: the doll and the locket are in the burnt farmhouse beside it."] = "Kasabanın içinden doğuya, Elbrim'in çiftliğine dön: bebek ve madalyon yanındaki yanık çiftlik evinde.",

	-- Step 46: The Rog'mar training grounds
	-- {area:16743} Rog'mar
	["The {area:16743} training grounds"] = "{area:16743} talim alanı",
	-- {area:16743} Rog'mar · {npc:263071} Blademaster Kaijo · {npc:263615} Krek the Noxious
	-- plural, as words: Rog'mar Grunts = {npc:255996} Rog'mar Grunt
	["North-east of Elbrim's farm, the Horde drills its trainees in the fields north of {area:16743}. Stay north of the fort: its guards are far above your level. The supply crates lie around the drill grounds. Three elites work this ground: {npc:263071} (42) walks among the trainees, {npc:263615} (42) lurks at the north end, and Komuk (45), a Horde elite, patrols the hills to the east; give each of them room.\nCareful: Rog'mar Grunts (55) guard the fort's north wall, around 59,39 to 61,41. Leave the crates and trainees by the wall and take the ones further north, around 57-61,34-37."] = "Elbrim'in çiftliğinin kuzeydoğusunda Horde, {area:16743} kuzeyindeki tarlalarda acemilerini eğitiyor. Kalenin kuzeyinde kal: muhafızları senin seviyenin çok üstünde. Erzak sandıkları talim alanlarının çevresinde. Bu alanda üç elit var: {npc:263071} (42) acemilerin arasında dolaşıyor, {npc:263615} (42) kuzey uçta pusuda, bir Horde eliti olan Komuk (45) da doğudaki tepelerde devriye geziyor; her birine yol ver.\nDikkat: Rog'mar Grunt yaratıkları (55) kalenin kuzey surunu, yaklaşık 59,39 ile 61,41 arasını koruyor. Surun yanındaki sandıkları ve acemileri bırak, daha kuzeydekileri, yaklaşık 57-61,34-37 çevresindekileri al.",

	-- Step 47: Blademaster Kaijo
	-- {npc:263071} Blademaster Kaijo
	["{npc:263071}, the elite, walks the training grounds."] = "Elit {npc:263071} talim alanında dolaşıyor.",

	-- Step 48: Sleebo Fizzlespout's workshop
	-- {npc:263367} Sleebo Fizzlespout
	["{npc:263367}'s workshop"] = "{npc:263367} atölyesi",
	-- {area:16743} Rog'mar · {npc:263367} Sleebo Fizzlespout · {area:16726} Bolder'ok
	["South-east, round {area:16743}'s east side, to {npc:263367}'s workshop on the hill. Komuk and the {area:16726} ogres walk the road east of the fort: let them pass before you cross it."] = "Güneydoğuya, {area:16743} kalesinin doğu yakasından dolaşıp tepedeki {npc:263367} atölyesine git. Komuk ve {area:16726} ogre'ları kalenin doğusundaki yolda dolaşıyor: karşıya geçmeden önce geçmelerine izin ver.",

	-- Step 49: The tallstriders and the marsh
	["The tallstriders and the marsh"] = "Tallstrider'lar ve bataklık",
	-- plural, as words: Roving Tallstriders = {npc:263348} Roving Tallstrider
	["The Roving Tallstriders graze the meadows south-west of the workshop; further south-west the marsh bubbles with gas: fill the vials at the vents."] = "Roving Tallstrider yaratıkları atölyenin güneybatısındaki çayırlarda otluyor; daha güneybatıda bataklık gazla fokurduyor: şişeleri gaz çıkışlarında doldur.",

	-- Step 50: Terral's Watch
	-- {npc:259352} Watcher Cornelius
	["{npc:259352}'s tower stands just south-west of the marsh."] = "{npc:259352} kulesi bataklığın hemen güneybatısında duruyor.",
	-- {quest:95066} The Rog'mar Situation · {npc:257558} Demar Brant · {area:16724} Farholde Keep
	["{quest:95066}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95066}: {area:16724} kalesindeki {npc:257558} için, sakla",

	-- Step 51: Farholde Keep
	-- {area:16724} Farholde Keep · {npc:257591} Ashe Amberhall · {npc:257558} Demar Brant · {area:16723} Sunnyglade · {npc:263089} Tessa Dawnbright · {npc:263613} Brother Lowley
	["South across the plains to {area:16724}: {npc:257591} and {npc:257558} stand together in the keep at the east end, {npc:257591} first, her news is what Brant's next orders wait on. With {area:16723} saved, {npc:263089} by the orchard and {npc:263613} by the barracks have work for you too."] = "Ovaların içinden güneye, {area:16724} kalesine: {npc:257591} ve {npc:257558} doğu ucundaki kalede birlikte duruyor; önce {npc:257591}: Brant'in sonraki emirleri onun haberlerini bekliyor. {area:16723} kurtarıldığı için meyve bahçesinin yanındaki {npc:263089} ve kışlanın yanındaki {npc:263613} de sana iş veriyor.",
	-- {quest:94907} A Small Favor
	["{quest:94907}: for later in this guide"] = "{quest:94907}: bu rehberde daha sonrası için",
	-- {quest:95329} Out in the Field · {npc:259352} Watcher Cornelius · {area:16729} Terral's Watch
	["{quest:95329}: for {npc:259352} at {area:16729}, keep it"] = "{quest:95329}: {area:16729} kulesindeki {npc:259352} için, sakla",
	-- {quest:94886} The Western Front
	["{quest:94886}: for later in this guide"] = "{quest:94886}: bu rehberde daha sonrası için",
	-- {npc:263613} Brother Lowley · {item:4338} Mageweave Cloth · {area:16723} Sunnyglade
	["{npc:263613}: twenty {item:4338}, from {area:16723}'s cultists and the pirates; hand it in when you are back"] = "{npc:263613}: {area:16723} tarikatçılarından ve korsanlardan yirmi {item:4338}; döndüğünde teslim et",

	-- Step 52: Tessa Dawnbright
	-- {npc:263089} Tessa Dawnbright
	["{npc:263089} stands west of the inn, by the orchard: the apples hang on the trees around it."] = "{npc:263089} hanın batısında, meyve bahçesinin yanında duruyor: elmalar çevresindeki ağaçlarda asılı.",

	-- Step 53: Coyote pelts
	["Coyote pelts"] = "Çakal postları",
	-- {area:16725} Wheeler's Grange
	-- plural, as words: Plains Coyotes = {npc:259267} Plains Coyote
	["The Plains Coyotes roam west and south-west of the keep, towards {area:16725}."] = "Plains Coyote yaratıkları kalenin batısında ve güneybatısında, {area:16725} çiftliğine doğru dolaşıyor.",

	-- Step 54: Tessa Dawnbright
	-- {quest:95961} Stepped Out · {npc:263120} Gray Dawnbright · {area:16727} Powderfuse Port
	["{quest:95961}: for {npc:263120} in {area:16727}, keep it"] = "{quest:95961}: {area:16727} limanındaki {npc:263120} için, sakla",

	-- Step 55: King of the Wild Plains
	-- {npc:263315} Ombassa · {area:16729} Terral's Watch
	["{npc:263315}, an elite lion (level 41), prowls the plains north of {area:16729}, on your way back north: grouping up is advised."] = "Elit bir aslan (seviye 41) olan {npc:263315}, kuzeye dönerken yolunun üstünde, {area:16729} kulesinin kuzeyindeki ovalarda dolaşıyor: grup kurman önerilir.",

	-- Step 57: Sleebo Fizzlespout
	-- {npc:263367} Sleebo Fizzlespout
	["North-east to {npc:263367}'s workshop. {npc:263367}'s stress test is a fight with his G45-B4G beside the workshop: hand the quest in once it's beaten."] = "Kuzeydoğuya, {npc:263367} atölyesine git. {npc:263367} adlı NPC'nin dayanıklılık testi, atölyenin yanındaki G45-B4G ile bir dövüş: yenince görevi teslim et.",
	["the stress test: beat G45-B4G beside the workshop"] = "dayanıklılık testi: atölyenin yanında G45-B4G'yi yen",

	-- Step 58: Powderfuse Port
	-- {area:16727} Powderfuse Port · {npc:255897} Friz Frazzlespark · {npc:263120} Gray Dawnbright · {npc:255894} Innkeeper Zizplink · {npc:259962} Fimbo Greasemitz · {npc:259961} Wharfmaster Whizzbuzz · {npc:260487} Gritta Chumwater · {npc:260565} Kor'gar · {npc:260560} Krikshank
	["East down the road to {area:16727}, the goblins' harbour. {npc:255897} keeps a stall at the west end of the docks; {npc:263120}, {npc:255894} and {npc:259962} are at the inn, and {npc:259961} works the north pier. Zizplink's drink needs three things the port's traders sell: the chum from {npc:260487}, the degreaser and the old poison from {npc:260565} and {npc:260560}, by {npc:255897}'s stall."] = "Yoldan doğuya, goblinlerin limanı {area:16727} içine in. {npc:255897} iskelelerin batı ucunda bir tezgâh tutuyor; {npc:263120}, {npc:255894} ve {npc:259962} handa, {npc:259961} de kuzey iskelede çalışıyor. Zizplink'in içkisi limanın tüccarlarının sattığı üç şey ister: {npc:260487} yanından yem, {npc:255897} tezgâhının yanındaki {npc:260565} ve {npc:260560} yanından yağ çözücü ve eski zehir.",
	-- {quest:95059} Frazzlespark's Crate · {npc:257558} Demar Brant · {area:16724} Farholde Keep
	["{quest:95059}: for {npc:257558} in {area:16724}, keep it"] = "{quest:95059}: {area:16724} kalesindeki {npc:257558} için, sakla",
	-- {item:271657} Fresh Chum · {npc:260487} Gritta Chumwater
	["{item:271657}, from {npc:260487}"] = "{item:271657}, kaynak: {npc:260487}",
	-- {item:271653} Goblin Degreaser · {npc:260565} Kor'gar
	["{item:271653}, from {npc:260565}"] = "{item:271653}, kaynak: {npc:260565}",
	-- {item:271654} Expired Poison · {npc:260560} Krikshank
	["{item:271654}, from {npc:260560}"] = "{item:271654}, kaynak: {npc:260560}",
	-- {object:628948} WANTED! (no name in this language: may be words) · {npc:260235} Trapclaw
	["The {object:628948} poster by the inn: {npc:260235}"] = "Hanın yanındaki {object:628948} ilanı: {npc:260235}",

	-- Step 59: WANTED: Old Rot-Chum
	-- {npc:257001} Old Rot-Chum
	["{npc:257001} is an elite (level 42) on the south shore: grouping up is advised."] = "{npc:257001}, güney kıyısında elit bir yaratık (seviye 42): grup kurman önerilir.",
	-- {object:628948} WANTED! (no name in this language: may be words)
	["The {object:628948} poster by the inn"] = "Hanın yanındaki {object:628948} ilanı",

	-- Step 60: The murlocs, south-west
	["The murlocs, south-west"] = "Murloclar, güneybatıda",
	-- {quest:95260} Terrors From the Deep · {npc:260231} Argo Brinewhistle
	["South-west along the shore from the port: the saltwater murlocs camp on the beaches. On the way, a painted hide is stretched beside the path: it starts {quest:95260} for {npc:260231} at the docks."] = "Limandan kıyı boyunca güneybatıya: tuzlu su murlocları kumsallarda kamp kurmuş. Yolda patikanın yanında boyalı bir post gerili: iskelelerdeki {npc:260231} için {quest:95260} görevini başlatır.",

	-- Step 62: Back through the port
	["Back through the port"] = "Limandan geri geç",
	["Back north along the shore: hand in the murlocs and the hide on the docks on your way to the crawlers."] = "Kıyı boyunca kuzeye dön: crawler'lara giderken iskelelerde murlocları ve postu teslim et.",
	-- {quest:95261} It Takes Guts
	["{quest:95261}: the beasts' entrails come as you go; the mushrooms are for later"] = "{quest:95261}: hayvanların bağırsakları yolda gelir; mantarlar sonrası için",

	-- Step 63: The crawlers and Trapclaw
	-- {npc:260235} Trapclaw
	["The crawlers and {npc:260235}"] = "Crawler'lar ve {npc:260235}",
	-- {npc:259962} Fimbo Greasemitz · {npc:260231} Argo Brinewhistle · {npc:260235} Trapclaw · {npc:259758} Gul'gash
	["North along the beach from the docks: the crawlers drop the meat for {npc:259962} and the spittle for Zizplink, and their entrails count for {npc:260231}. {npc:260235}, a big crab, scuttles along the rocks east of the docks. {npc:259758}, a rare elite of level 49, roams this coast from the docks up to the pirates' camp: if you see him, keep well away."] = "İskelelerden kumsal boyunca kuzeye: crawler'lar {npc:259962} için et, Zizplink için salya düşürür, bağırsakları da {npc:260231} için sayılır. Büyük bir yengeç olan {npc:260235}, iskelelerin doğusundaki kayalıklarda geziniyor. 49. seviye rare elit {npc:259758} bu kıyıda iskelelerden korsanların kampına kadar dolaşıyor: görürsen ondan iyice uzak dur.",

	-- Step 64: The Eastsea pirates
	["The Eastsea pirates"] = "Eastsea korsanları",
	-- {npc:259758} Gul'gash
	["North-east along the coast to the pirates' camp on the cliffs. The buccaneers and musketeers carry the smuggled goods. {npc:259758} walks the camp too: keep an eye out for him."] = "Kıyı boyunca kuzeydoğuya, kayalıklardaki korsan kampına git. Buccaneer ve Musketeer'lar kaçak malları taşıyor. {npc:259758} de kampta dolaşıyor: ona göz kulak ol.",

	-- Step 65: Powderfuse Port
	["Back to the port, from the north pier west through the docks."] = "Limana dön: kuzey iskeleden batıya, iskelelerin içinden.",
	-- {quest:95122} Unchecked Expansion
	["{quest:95122}: for later in this guide"] = "{quest:95122}: bu rehberde daha sonrası için",
	-- {quest:95123} A Blast Ye Scurvy Dogs!
	["{quest:95123}: for later in this guide"] = "{quest:95123}: bu rehberde daha sonrası için",
	-- {quest:95975} Her World
	["{quest:95975}: for later, the wildflowers west of the port"] = "{quest:95975}: sonrası için, limanın batısındaki kır çiçekleri",
	-- {quest:95293} Smuggler's Special · {npc:260390} Captain Bentcoin
	["{quest:95293}: for {npc:260390} at the pirates' camp"] = "{quest:95293}: korsanların kampındaki {npc:260390} için",

	-- Step 67: Beast Entrails as you go
	-- {item:268632} Beast Entrails
	["{item:268632} as you go"] = "Yol boyunca {item:268632}",
	-- {zone:2548} Riverglades · {item:268632} Beast Entrails · {npc:260231} Argo Brinewhistle · {npc:257001} Old Rot-Chum · {npc:263380} Ghostmaw
	["Most beasts in the {zone:2548} drop {item:268632} for {npc:260231}: the shore crawlers on this coast and the boars on the ridge west of the pirates.\nCareful: {npc:257001} (elite, 42), Komuk (a Horde elite, 45) and {npc:263380} (elite, 42) range over the zone's wilds: take your beasts away from them."] = "{zone:2548} bölgesindeki hayvanların çoğu {npc:260231} için {item:268632} düşürür: bu kıyıdaki crawler'lar ve korsanların batısındaki sırttaki yaban domuzları.\nDikkat: {npc:257001} (elit, 42), Komuk (Horde eliti, 45) ve {npc:263380} (elit, 42) bölgenin vahşi kesimlerinde dolaşıyor: hayvanlarını onlardan uzakta avla.",

	-- Step 68: Level 44.4 on the Eastsea pirates
	["Level 44.4 on the Eastsea pirates"] = "Eastsea korsanlarıyla seviye 44.4",
	-- {npc:259758} Gul'gash · {area:1517} Uldaman
	["Before the second wave: its raiders and bombardiers (43-45) and the pirates' ships after them are a level over you below 44.4. Top up on the first camp's buccaneers and musketeers (41-43) at its south-west end, away from the port. {npc:259758}, a rare elite of level 49, roams these cliffs: if you see him, keep well away. Or, with a group, run the {area:1517} dungeon instead."] = "İkinci dalgadan önce: akıncıları ve bombardıman topçuları (43-45), ardından da korsan gemileri 44.4'ün altında senden bir seviye yüksek. Limandan uzakta, ilk kampın güneybatı ucundaki Buccaneer ve Musketeer yaratıklarıyla (41-43) seviyeni tamamla. 49. seviye rare elit {npc:259758} bu kayalıklarda dolaşıyor: görürsen ondan iyice uzak dur. Ya da grubun varsa onun yerine {area:1517} zindanına koş.",
	-- {npc:257901} Eastsea Buccaneer
	["grind on {npc:257901}"] = "Kas: {npc:257901}",

	-- Step 69: The pirates' second wave
	["The pirates' second wave"] = "Korsanların ikinci dalgası",
	-- {npc:259758} Gul'gash
	["North along the coast from the port: the Eastsea raiders and bombardiers have dug in on the slopes west of the buccaneers' camp, among their powder kegs. They stand close together: pull them one at a time. {npc:259758}, a rare elite of level 49, roams these cliffs and the beach below: if you see him, keep well away."] = "Limandan kıyı boyunca kuzeye: Eastsea akıncıları ve bombardıman topçuları, Buccaneer kampının batısındaki yamaçlarda barut fıçılarının arasına yerleşmiş. Birbirine yakın duruyorlar: tek tek çek. 49. seviye rare elit {npc:259758} bu kayalıklarda ve aşağıdaki kumsalda dolaşıyor: görürsen ondan iyice uzak dur.",

	-- Step 70: Captain Bentcoin
	-- {npc:260390} Captain Bentcoin · {npc:260391} Captain Haynes
	["East along the cliffs to the far end of the pirates' camp: {npc:260390} waits by the water, {npc:260391} beside him."] = "Kayalıklar boyunca doğuya, korsan kampının en ucuna: {npc:260390} suyun kenarında bekliyor, {npc:260391} de yanında.",

	-- Step 71: Powderfuse Port
	["Back to the port."] = "Limana dön.",

	-- Step 72: The pirates' ships
	["The pirates' ships"] = "Korsan gemileri",
	-- {quest:95124} Admiral Lamora · {npc:259758} Gul'gash
	["Out to the pirates' cliffs once more. Plant Whizzbuzz's charges on the three ships moored below the camp, south to north; {quest:95124} (level 45) stands by the middle one, with her loot chest beside her. Keep an eye out for {npc:259758} on the way."] = "Bir kez daha korsanların kayalıklarına çık. Whizzbuzz'ın patlayıcılarını kampın aşağısında demirli üç gemiye, güneyden kuzeye yerleştir; {quest:95124} (seviye 45) ortadakinin yanında, ganimet sandığıyla birlikte duruyor. Yolda {npc:259758} yaratığına göz kulak ol.",
	-- {item:268505} Remote Explosive Charge
	["{item:268505}, the southern ship"] = "{item:268505}, güneydeki gemi",
	["the middle ship"] = "ortadaki gemi",
	["the northern ship"] = "kuzeydeki gemi",

	-- Step 73: Rotflesh Mushrooms
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom
	["Rotflesh Mushrooms"] = "Rotflesh Mushroom mantarları",
	-- plural, as words: Rotflesh Mushrooms = {item:268664} Rotflesh Mushroom · Mature Paletusks = {npc:255851} Mature Paletusk
	["West from the northern ship, up the ridge: the Rotflesh Mushrooms grow among the rocks, close to the Twilight ogres' camp. The Mature Paletusks on the ridge give entrails too."] = "Kuzeydeki gemiden batıya, sırta çık: Rotflesh Mushroom mantarları kayaların arasında, Twilight ogre'larının kampına yakın yetişiyor. Sırttaki Mature Paletusk yaratıkları da bağırsak verir.",

	-- Step 74: Bolder'ok
	-- {area:16726} Bolder'ok · {npc:259057} Dunston Willis
	["North-west to {area:16726}, the ogres' town. Its ogres side with the Horde and attack you on sight, and Clugfist on his hill in the middle is an elite (level 50): keep to the town's north-eastern edge, where {npc:259057} hides."] = "Kuzeybatıya, ogre'ların kasabası {area:16726} içine git. Ogre'ları Horde'un yanında ve seni görür görmez saldırır; ortadaki tepesindeki Clugfist de elit (seviye 50): {npc:259057} adlı NPC'nin saklandığı kasabanın kuzeydoğu kenarında kal.",

	-- Step 75: Gronok's Key
	-- {npc:263749} Gronok the Butcher · {npc:259057} Dunston Willis · {item:275043} Bloodmaster's Ring
	["{npc:263749} (level 44) carries the key: he paces the lanes south of {npc:259057}'s hut.\nThe {item:275043} lies just west of the lanes: its fighters (elites, 41-45) only fight in a bout, so leave them be."] = "Anahtar {npc:263749} (seviye 44) yaratığında: {npc:259057} adlı NPC'nin kulübesinin güneyindeki sokaklarda dolaşıyor.\n{item:275043} sokakların hemen batısında: dövüşçüleri (elit, 41-45) yalnızca bir maçta dövüşür, onları rahat bırak.",

	-- Step 76: Dunston Willis
	-- {npc:259057} Dunston Willis · {area:16726} Bolder'ok
	["Free him, then get him out: {npc:259057} fights his way out of {area:16726}, and you keep the ogres off him. If he falls, take the quest from him again."] = "Onu serbest bırak, sonra dışarı çıkar: {npc:259057} dövüşerek {area:16726} kasabasından çıkar, sen de ogre'ları ondan uzak tutarsın. Düşerse görevi ondan yeniden al.",
	-- {npc:259057} Dunston Willis · {area:16726} Bolder'ok
	["help {npc:259057} break out of {area:16726}"] = "{npc:259057} adlı NPC'nin {area:16726} kasabasından kaçmasına yardım et",

	-- Step 77: Finish the Beast Entrails
	-- {item:268632} Beast Entrails
	["Finish the {item:268632}"] = "{item:268632} işini bitir",
	-- {npc:259758} Gul'gash
	["South-east out of the hills towards the port: the shore crawlers on the beach north of the docks are the quickest entrails. {npc:259758} wanders down to this beach too."] = "Tepelerden güneydoğuya, limana doğru: en hızlı bağırsaklar iskelelerin kuzeyindeki kumsalda bulunan crawler'lar. {npc:259758} bu kumsala da iner.",

	-- Step 78: Powderfuse Port
	["Down to the port."] = "Limana in.",
	-- {quest:95267} The Monster Surfaces · {npc:257001} Old Rot-Chum
	["{quest:95267}: a big beast in the shallows south-west of the port, near {npc:257001}, the elite"] = "{quest:95267}: limanın güneybatısındaki sığlıklarda, elit {npc:257001} yakınında büyük bir hayvan",

	-- Step 79: The Monster Surfaces
	-- {npc:260244} Monstrous Threshadon · {npc:257001} Old Rot-Chum
	["The {npc:260244} prowls the shallows south-west of the port, below the murlocs' beaches. {npc:257001}, an elite, walks the shore close by: give him room."] = "{npc:260244}, limanın güneybatısındaki sığlıklarda, murloc kumsallarının aşağısında dolaşıyor. Elit {npc:257001} yakında kıyıda yürüyor: ona yol ver.",

	-- Step 81: The meadows
	["The meadows"] = "Çayırlar",
	-- {npc:263367} Sleebo Fizzlespout
	["West of the port, the wildflowers grow in the meadows below {npc:263367}'s workshop."] = "Limanın batısında, kır çiçekleri {npc:263367} adlı NPC'nin atölyesinin aşağısındaki çayırlarda yetişiyor.",

	-- Step 82: Farholde Keep
	-- {area:16724} Farholde Keep · {npc:257558} Demar Brant
	["South-west across the plains to {area:16724}: {npc:257558} in the keep at the east end."] = "Ovaların içinden güneybatıya, {area:16724} kalesine: {npc:257558} doğu ucundaki kalede.",

