	["West through the keep: {npc:263089} by the orchard, then the cathedral and {npc:259859} south of the inn if you have their errands."] = "Kalenin içinden batıya: meyve bahçesinin yanındaki {npc:263089}, sonra işleri sendeyse katedral ve hanın güneyindeki {npc:259859}.",

